name: Auto Assign Milestone

on:
  pull_request:
    types: [opened, synchronize, reopened, edited, closed]

permissions:
  contents: read
  pull-requests: write
  issues: write

jobs:
  assign-milestone:
    runs-on: ubuntu-latest
    steps:
      - name: Assign milestone based on target branch
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const baseBranch = pr.base.ref;
            const repo = context.repo;

            // Fetch all milestones
            const { data: milestones } = await github.rest.issues.listMilestones({
              owner: repo.owner,
              repo: repo.repo,
              state: 'all',
              per_page: 100
            });

            // Helper to parse numeric value from milestone title
            const parseMilestoneNumber = (title) => {
              const match = title.match(/^\\d+(?:\\.\\d+)?(?:\\.\\d+)?$/);
              return match ? parseFloat(match[0]) : null;
            };

            let targetMilestone = null;

            if (baseBranch === 'main') {
              // Highest closed milestone
              const closed = milestones.filter(m => m.state === 'closed');
              let highestClosed = null;
              for (const m of closed) {
                const num = parseMilestoneNumber(m.title);
                if (num !== null && (highestClosed === null || num > highestClosed)) {
                  highestClosed = num;
                }
              }

              // Lowest open milestone greater than highestClosed
              const open = milestones.filter(m => m.state === 'open');
              const candidates = [];
              for (const m of open) {
                const num = parseMilestoneNumber(m.title);
                if (num !== null && (highestClosed === null || num > highestClosed)) {
                  candidates.push({ num, id: m.number, title: m.title });
                }
              }
              if (candidates.length > 0) {
                candidates.sort((a, b) => a.num - b.num);
                targetMilestone = candidates[0].id;
              }
            } else if (baseBranch.startsWith('release/')) {
              // Map release branch to milestone title
              const releaseMap = {
                'release/9.4': '9.4.1',
                // Add more mappings here if needed
              };
              const milestoneTitle = releaseMap[baseBranch];
              if (milestoneTitle) {
                const m = milestones.find(m => m.title === milestoneTitle);
                if (m) targetMilestone = m.number;
              }
            }

            if (targetMilestone) {
              await github.rest.issues.update({
                owner: repo.owner,
                repo: repo.repo,
                issue_number: pr.number,
                milestone: targetMilestone
              });
              console.log(`Assigned milestone #${targetMilestone} to PR #${pr.number}`);
            } else {
              console.log(`No milestone assigned for PR #${pr.number} on branch ${baseBranch}`);
            }
